bool pm_face_tarot_embedded_card(int idx, const uint16_t **rgb, const uint8_t **mask, int *w, int *h) {
  if (idx < 0 || idx >= static_cast<int>(sizeof(kTarotAssets) / sizeof(kTarotAssets[0])) || !rgb || !mask || !w || !h) {
    return false;
  }
  *rgb = kTarotAssets[idx].rgb;
  *mask = kTarotAssets[idx].mask;
  *w = kTarotAssets[idx].w;
  *h = kTarotAssets[idx].h;
  return true;
}
